F_signature:
MeasureTheory.lcondExp_const.{u_1} {α : Type u_1} {m m₀ : MeasurableSpace α} {μ : MeasureTheory.Measure α}
  [MeasureTheory.SigmaFinite μ] (hm : m ≤ m₀) (c : ENNReal) [MeasureTheory.IsFiniteMeasure μ] :
  (MeasureTheory.lcondExp m μ fun x => c) = fun x => c

MeasureTheory.Integrable.fun_mul_of_top_right.{u_1, u_3} {α : Type u_1} {𝕜 : Type u_3} {mα : MeasurableSpace α}
  {μ : MeasureTheory.Measure α} [NormedField 𝕜] {f φ : α → 𝕜} (hf : MeasureTheory.Integrable f μ)
  (hφ : MeasureTheory.MemLp φ ⊤ μ) : MeasureTheory.Integrable (fun x => φ x * f x) μ

Specification.isssdFun_apply.{u_1, u_2} {S : Type u_1} {E : Type u_2} {mE : MeasurableSpace E}
  (ν : MeasureTheory.Measure E) (Λ : Finset S) :
  ⇑(Specification.isssdFun ν Λ) = fun η => MeasureTheory.Measure.map (juxt (↑Λ) η) (MeasureTheory.Measure.pi fun x => ν)

Specification.modification_apply.{u_1, u_2} {S : Type u_1} {E : Type u_2} {mE : MeasurableSpace E}
  (γ : Specification S E) (ρ : Finset S → (S → E) → ENNReal) (hρ : Specification.IsModifier γ ρ) (Λ : Finset S)
  (η : S → E) : ((Specification.modification γ ρ hρ) Λ) η = MeasureTheory.Measure.withDensity ((γ Λ) η) (ρ Λ)

Specification.isGibbsMeasure_isssd_infinitePi.{u_1, u_2} {S : Type u_1} {E : Type u_2} {mE : MeasurableSpace E}
  (ν : MeasureTheory.Measure E) [MeasureTheory.IsProbabilityMeasure ν] :
  Specification.IsGibbsMeasure (Specification.isssd ν) (MeasureTheory.Measure.infinitePi fun x => ν)

Specification.IsModifier.measurable.{u_1, u_2} {S : Type u_1} {E : Type u_2} {mE : MeasurableSpace E}
  {γ : Specification S E} {ρ : Finset S → (S → E) → ENNReal} (self : Specification.IsModifier γ ρ) (Λ : Finset S) :
  Measurable (ρ Λ)

MeasureTheory.lcondExp_add.{u_1} {α : Type u_1} {m m₀ : MeasurableSpace α} {μ : MeasureTheory.Measure α}
  [MeasureTheory.SigmaFinite μ] {f g : α → ENNReal} :
  MeasureTheory.lcondExp m μ (f + g) =ᵐ[μ] MeasureTheory.lcondExp m μ f + MeasureTheory.lcondExp m μ g

ProbabilityTheory.Kernel.IsCondExp.condExp_ae_eq_kernel_apply.{u_1} {X : Type u_1} {𝓑 𝓧 : MeasurableSpace X}
  {π : ProbabilityTheory.Kernel X X} {μ : MeasureTheory.Measure X} [self : ProbabilityTheory.Kernel.IsCondExp π μ]
  ⦃A : Set X⦄ : MeasurableSet A → μ[Set.indicator A 1 | 𝓑] =ᵐ[μ] fun a => ENNReal.toReal ((π a) A)

MeasureTheory.lcondExp_bot'.{u_1} {α : Type u_1} {m₀ : MeasurableSpace α} {μ : MeasureTheory.Measure α}
  [MeasureTheory.SigmaFinite μ] [hμ : NeZero μ] (f : α → ENNReal) :
  MeasureTheory.lcondExp ⊥ μ f = fun x => (ENNReal.toNNReal (μ Set.univ))⁻¹ • ∫⁻ (x : α), f x ∂μ

MeasureTheory.lcondExp_smul.{u_1} {α : Type u_1} {m m₀ : MeasurableSpace α} {μ : MeasureTheory.Measure α}
  [MeasureTheory.SigmaFinite μ] (c : NNReal) (f : α → ENNReal) :
  MeasureTheory.lcondExp m μ (c • f) =ᵐ[μ] c • MeasureTheory.lcondExp m μ f

Specification.IsModifier.isConsistent.{u_1, u_2} {S : Type u_1} {E : Type u_2} {mE : MeasurableSpace E}
  {γ : Specification S E} {ρ : Finset S → (S → E) → ENNReal} (self : Specification.IsModifier γ ρ) :
  IsConsistent (Specification.modificationKer (⇑γ) ρ ⋯)

MeasureTheory.ae_eq_lcondExp_of_forall_setLIntegral_eq.{u_1} {α : Type u_1} {m m₀ : MeasurableSpace α}
  {μ : MeasureTheory.Measure α} [MeasureTheory.SigmaFinite μ] (hm : m ≤ m₀)
