MeasureTheory.ae_eq_of_forall_setLIntegral_eq_of_sigmaFinite'.{u_1} {α : Type u_1} {m m0 : MeasurableSpace α}
  {μ : MeasureTheory.Measure α} (hm : m ≤ m0) [MeasureTheory.SigmaFinite (MeasureTheory.Measure.trim μ hm)]
