MeasureTheory.lcondExp_congr_ae.{u_1} {α : Type u_1} {m m₀ : MeasurableSpace α} {μ : MeasureTheory.Measure α}
  [MeasureTheory.SigmaFinite μ] {f g : α → ENNReal} (h : f =ᵐ[μ] g) :
