MeasureTheory.toReal_ae_eq_indicator_condExp_of_forall_setLIntegral_eq.{u_1} {α : Type u_1} {m m0 : MeasurableSpace α}
  {μ : MeasureTheory.Measure α} [MeasureTheory.IsFiniteMeasure μ] (hm : m ≤ m0) {g : α → ENNReal} {s : Set α}
  (hs₀ : MeasurableSet s) (hgm : MeasureTheory.AEStronglyMeasurable g μ)
  (hg_int_finite : ∀ (t : Set α), MeasurableSet t → μ t < ⊤ → ∫⁻ (a : α) in t, g a ∂μ ≠ ⊤)
  (hg_eq : ∀ (t : Set α), MeasurableSet t → μ t < ⊤ → ∫⁻ (a : α) in t, g a ∂μ = μ (s ∩ t)) :
  (fun a => ENNReal.toReal (g a)) =ᵐ[μ] μ[Set.indicator s 1 | m]

